package e.e.a;
import java.io.*;import java.lang.reflect.*;import java.util.*;import android.content.*;import android.preference.PreferenceManager;
/** Folder-first behavior: no video cache is created at an implicit private location. */
public class CacheDefaultTest{
 static void check(boolean b,String m){if(!b)throw new AssertionError(m);}
 static final Map<String,String> values=new HashMap<>();static int writes;
 static Object preferences(Class<?> type){return Proxy.newProxyInstance(type.getClassLoader(),new Class[]{type},(p,m,a)->{String n=m.getName();if(n.equals("getString"))return values.containsKey(a[0])?values.get(a[0]):a[1];if(n.equals("edit"))return preferences(SharedPreferences.Editor.class);if(n.equals("putString")){writes++;values.put((String)a[0],(String)a[1]);return p;}if(n.equals("remove")){values.remove(a[0]);return p;}if(n.equals("commit"))return true;if(n.equals("apply"))return null;throw new AssertionError(n);});}
 public static void main(String[] args)throws Exception{values.clear();PreferenceManager.prefs=(SharedPreferences)preferences(SharedPreferences.class);File base=new File(args[0]).getAbsoluteFile();File external=new File(base,"external"),internal=new File(base,"internal");external.mkdirs();internal.mkdirs();Context c=new Context(external,internal);
 String root=CacheFolders.root(c);check(root.equals("/@nicoid-cache/unselected"),"no private fallback");check(!new File(external,"nicoid/nicoid_cache").exists(),"no private video directory created");check(!CacheFolders.workerReady(c),"worker blocked before folder selection");
 Intent download=new Intent(new ComponentName("com.sauzask.nicoid.NicoidDownloadCache"));check(CacheFolders.startService(c,download)==null&&c.starts==0,"background worker requires folder");check(CacheFolders.startForegroundService(c,download)==null&&c.starts==0,"foreground worker requires folder");check(android.widget.Toast.messages==2,"non-activity requests explain folder selection");
 CacheFile aux=new CacheFile(root+"/nicoid/history.json");check(aux.getParentFile().equals(new File(external,"nicoid")),"auxiliary history remains private");check(!new File(internal,"nicoid/nicoid_cache").exists(),"no internal fallback video directory");
 values.put("cache_tree_uri","content://test/tree/chosen");String selected=CacheFolders.root(c);check(selected.startsWith("/@nicoid-cache/")&&!selected.endsWith("unselected"),"selected folder uses SAF");check(values.containsKey("cache_tree_"+selected.substring("/@nicoid-cache/".length())),"selected tree bookmark retained");int before=writes;for(int n=0;n<100;n++)check(CacheFolders.root(c).equals(selected),"stable cache root");check(writes==before,"repeated root reads do not rewrite preferences");values.remove("cache_tree_uri");check(CacheFolders.root(c).equals(root),"reset does not re-enable private storage");
 ComponentName other=new ComponentName("com.sauzask.nicoid.OtherService");check(CacheFolders.startService(c,new Intent(other))==other&&c.starts==1,"other services retain behavior");
 System.out.println("Folder-first storage/service policy: 13 checks passed");}
}
